 private static String notice(RuntimeException e){return e.getMessage()==null?"Your nap could not be saved. Try again.":e.getMessage();}
 @Override protected void onResume(){super.onResume();resumed=true;if(draft!=null&&pending())try{String denied=Naps.ports.create(getApplicationContext()).access();if(!denied.isEmpty()){Naps.reconcile(this,draft.id);reload();render();}}catch(RuntimeException failure){error=notice(failure);render();}if(preview!=null)preview.visible(hasWindowFocus());if(tone!=null)tone.resume();handler.post(tick);}
