 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);if(preview!=null)preview.visible(focus&&resumed);if(tone!=null)tone.focus(focus&&route.equals("sound"));}
